                className={`cat-btn ${activeCategory === cat ? 'active' : ''}`}
                onClick={() => setActiveCategory(cat)}
              >
                {cat}
              </button>
            ))}
          </div>
        </div>

        {/* Courses Grid */}
        <div className="catalog-grid">
          {filtered.length > 0 ? (
            filtered.map((course, i) => {
              const sc = statusColors[course.badge] || statusColors["NEW"];
              return (
                <motion.div
                  key={course.title}
                  className="course-card-modern"
                  initial={{ opacity: 0, y: 30 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  viewport={{ once: true }}
                  transition={{ duration: 0.5, delay: i * 0.05 }}
                  whileHover={{ y: -10 }}
                >
                  {/* Image Banner */}
                  <div className="card-img-banner">
                    <img src={course.image} alt={course.title} />
                    <span className="card-category-tag">{course.category}</span>
                  </div>

                  <div className="card-content-modern">
                    {/* Status Pill */}
                    <div className="card-status-row">
                      <span className="card-status-pill" style={{ background: sc.bg, color: sc.color }}>
                        {course.badge}
                      </span>
                    </div>

                    <h3 className="card-title-modern">{course.title}</h3>

                    {/* Stats Row */}
                    <div className="card-stats-modern">
                      <div className="stat">
                        <Users size={14} />
                        <span>{course.students}</span>
                      </div>
                      <div className="stat">
                        <Star size={14} fill="#f59e0b" color="#f59e0b" />
                        <span>{course.rating}</span>
                      </div>
                      <div className="stat">
                        <Clock size={14} />
                        <span>{course.duration}</span>
                      </div>
                    </div>

                    {/* Footer */}
                    <div className="card-footer-modern" style={{ justifyContent: 'space-between' }}>
                      <div className="course-id-display">
                        {course.courseId}
                      </div>
                      <button className="btn-primary mini" onClick={handleEnroll}>
                        <span>Enroll</span>
                        <ArrowRight size={14} />
                      </button>
                    </div>
                  </div>
                </motion.div>
              );
